package io.github.jesterportfolio.hearth.verification;

import io.github.jesterportfolio.hearth.survival.economy.*;
import io.github.jesterportfolio.hearth.inventory.*;
import io.github.jesterportfolio.hearth.economy.*;
import io.github.jesterportfolio.hearth.persistence.*;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.*;
import org.bukkit.*;
import org.bukkit.inventory.ItemStack;
import org.bukkit.plugin.java.JavaPlugin;

/** 실제 Paper 코덱/PG + 제어 Port. 실제 Player/인증/클릭/Player.saveData를 합성하지 않습니다. */
public final class NativeEconomyVerification {
    private static final UUID FIRST=new UUID(0x4e4154,1),SECOND=new UUID(0x4e4154,2),ROLLBACK=new UUID(0x4e4154,3),UNKNOWN=new UUID(0x4e4154,4),STALE=new UUID(0x4e4154,5);
    private static UUID request(long n){return new UUID(0x4e415452,n);}
    private NativeEconomyVerification(){}
    private static void check(JavaPlugin p,boolean value,String name){if(!value)throw new IllegalStateException("NATIVE_CHECK_"+name);p.getLogger().info("HEARTH_NATIVE_ECONOMY_CHECK PASS "+name);}
    private static <T>CompletionStage<T> on(CompletionStage<T> work,Executor owner){return work.thenApplyAsync(v->v,owner);}
    private static final class InventoryPort implements NativeTransactions.Port{
        final UUID id;final PaperInventoryCodec codec;InventoryPayload payload;boolean alive=true,frozen;int saves,applies;
        InventoryPort(UUID id,PaperInventoryCodec codec,int ingots,boolean ore){this.id=id;this.codec=codec;var slots=new ItemStack[41];slots[0]=new ItemStack(Material.IRON_INGOT,ingots);slots[1]=new ItemStack(Material.STONE,24);if(ore)slots[2]=new ItemStack(Material.IRON_ORE,1);slots[36]=new ItemStack(Material.IRON_HELMET);slots[40]=new ItemStack(Material.TORCH,5);payload=codec.encode(slots);}
        public UUID player(){return id;}public boolean current(){return alive;}public InventoryPayload capture(){return payload;}public boolean same(InventoryPayload before){return codec.equivalent(payload,before);}public void freeze(boolean value){frozen=value;}public void saveNative(){saves++;}public void validate(InventoryPayload after){codec.decode(after);}public void apply(InventoryPayload after){payload=after;applies++;}public void notice(String code){}
    }
    public static CompletionStage<Void> run(JavaPlugin p,SurvivalEconomy e,PostgresProgressStore db,String action){
        final Path root;try{if(!Set.of("prepare","resume").contains(action))throw new IllegalArgumentException();root=IsolatedPaths.require(Path.of(System.getProperty("hearth.native.economy.verification.root","")),"hearth-native-economy-run.");if(!Path.of("").toRealPath().equals(root.resolve("server"))||!Files.readString(root.resolve(".hearth-native-economy-isolated")).equals("Hearth native economy isolated v1\n")||!Bukkit.getOnlinePlayers().isEmpty()||!Bukkit.getOnlineMode()||!Bukkit.hasWhitelist()||!Bukkit.getIp().equals("127.0.0.1")||e.phase()!=SurvivalEconomy.Phase.READY)throw new IllegalStateException("NATIVE_PROBE_GATE");Files.createFile(root.resolve("probe-"+action+".started"));}catch(Exception failure){return CompletableFuture.failedFuture(failure);}
        var owner=e.owner;return on(db.module("native_probe_directory",c->{try(var st=c.createStatement();var rows=st.executeQuery("SHOW data_directory")){if(!rows.next()||!Path.of(rows.getString(1)).toRealPath().equals(root.resolve("data")))throw new IllegalStateException("NATIVE_PROBE_DATABASE_ROOT");}return null;}),owner).thenCompose(v->action.equals("prepare")?prepare(p,e,root):resume(p,e,root));
    }
    private static CompletionStage<Void> prepare(JavaPlugin p,SurvivalEconomy e,Path root){
        var codec=new PaperInventoryCodec();var a=new InventoryPort(FIRST,codec,12,false);var b=new InventoryPort(SECOND,codec,5,true);var r=new InventoryPort(ROLLBACK,codec,4,false);var u=new InventoryPort(UNKNOWN,codec,4,false);var s=new InventoryPort(STALE,codec,4,false);var empty=codec.encode(new ItemStack[41]);var first=e.store.context(e.settings.realm(),FIRST);var second=e.store.context(e.settings.realm(),SECOND);var rollback=e.store.context(e.settings.realm(),ROLLBACK);var unknown=e.store.context(e.settings.realm(),UNKNOWN);var stale=e.store.context(e.settings.realm(),STALE);var key=new EconomyContent.Key("capital","iron_ingot");var expected=new Properties();
        check(p,e.menu.liveMerchants()==e.merchants.all().size(),"actual_configured_merchants_loaded_without_Player");
        CompletionStage<Void> work=CompletableFuture.completedFuture(null);for(var context:List.of(first,second,rollback,unknown,stale))work=work.thenCompose(v->e.store.ensureAccount(context,empty).thenAccept(account->{if(account.balance()!=0)throw new IllegalStateException("NONZERO_INITIAL_BALANCE");}));
        return on(work,e.owner).thenCompose(v->on(e.store.offer(first,key),e.owner)).thenCompose(offer->e.transactions.begin(request(1),"SHOP",List.of(a),e.ledger.shop(first,offer,3,false,request(1),EconomyStore.Probe.NONE))).thenCompose(v->on(e.store.account(first),e.owner)).thenAccept(account->{check(p,codec.decode(a.payload)[0].getAmount()==9&&account.balance()>0&&codec.equivalent(a.payload,account.inventory().payload())&&!a.frozen&&a.saves==2,"latest_native_items_sell_atomically_with_zero_initial_balance_and_no_join_restore");})
            .thenCompose(v->on(e.store.offer(first,key),e.owner)).thenCompose(offer->e.transactions.begin(request(2),"SHOP",List.of(a),e.ledger.shop(first,offer,1,true,request(2),EconomyStore.Probe.NONE))).thenAccept(v->{var slots=codec.decode(a.payload);check(p,slots[0].getAmount()==10&&slots[1].getAmount()==24&&slots[36].getType()==Material.IRON_HELMET&&slots[40].getAmount()==5,"native_buy_preserves_other_storage_armor_and_offhand");})
            .thenCompose(v->on(e.store.account(first).thenCombine(e.store.account(second),(x,y)->x.balance()+y.balance()),e.owner)).thenCompose(total->{var request=new EconomyStore.PeerRequest(request(3),first,second,new PeerTrade.Offer(Map.of("iron_ingot",2),10),new PeerTrade.Offer(Map.of("iron_ore",1),0));return e.transactions.begin(request.id(),"PEER",List.of(a,b),e.ledger.peer(request,EconomyStore.Probe.NONE)).thenCompose(x->on(e.store.account(first).thenCombine(e.store.account(second),(left,right)->left.balance()+right.balance()),e.owner)).thenAccept(after->check(p,total.equals(after)&&codec.decode(a.payload)[0].getAmount()==8&&codec.decode(b.payload)[0].getAmount()==7&&!a.frozen&&!b.frozen,"peer_goods_and_money_commit_once_for_both_native_payloads"));})
            .thenCompose(v->on(e.store.offer(rollback,key),e.owner)).thenCompose(offer->{var before=r.payload;var market=offer.market();return on(e.transactions.begin(request(4),"SHOP",List.of(r),e.ledger.shop(rollback,offer,1,false,request(4),EconomyStore.Probe.ROLLBACK)).handle((x,error)->error!=null),e.owner).thenCompose(failed->on(e.store.offer(rollback,key),e.owner).thenAccept(after->check(p,failed&&r.payload.equals(before)&&r.applies==0&&r.frozen&&e.journal.held(ROLLBACK)&&after.balance()==0&&after.market().equals(market),"real_23514_trade_rollback_keeps_native_original_and_market_balance_unchanged")));})
            .thenCompose(v->on(e.store.offer(unknown,key),e.owner)).thenCompose(offer->{var before=u.payload;return on(e.transactions.begin(request(5),"SHOP",List.of(u),e.ledger.shop(unknown,offer,1,false,request(5),EconomyStore.Probe.COMMIT_UNKNOWN)).handle((x,error)->error!=null),e.owner).thenCompose(failed->on(e.store.receipt(unknown,request(5)),e.owner).thenAccept(receipt->check(p,failed&&receipt.isPresent()&&receipt.get().account().balance()>0&&u.payload.equals(before)&&u.applies==0&&e.journal.held(UNKNOWN),"commit_unknown_keeps_receipt_and_native_original_without_automatic_reissue")));})
            .thenCompose(v->on(e.store.offer(stale,key),e.owner)).thenCompose(offer->{var gate=new CompletableFuture<Void>();var operation=e.ledger.shop(stale,offer,1,false,request(6),EconomyStore.Probe.NONE);var result=e.transactions.begin(request(6),"SHOP",List.of(s),(before,valid)->gate.thenComposeAsync(x->operation.execute(before,valid),e.owner));s.alive=false;e.transactions.invalidate(STALE);gate.complete(null);return on(result.handle((x,error)->error!=null),e.owner).thenCompose(x->waitSettled(p,e,0)).thenCompose(x->on(e.store.receipt(stale,request(6)),e.owner)).thenAccept(receipt->check(p,receipt.isEmpty()&&s.applies==0&&e.journal.held(STALE),"revoked_life_fence_rejects_real_DB_trade_and_old_callback_application"));})
            .thenCompose(v->on(e.store.event(e.settings.realm(),request(7),"demand_surge"),e.owner)).thenCompose(v->e.advanceTick()).thenCompose(v->e.advanceTick()).thenCompose(v->e.advanceTick()).thenCompose(v->e.advanceTick())
            .thenCompose(v->{var merchant=e.merchants.first();var report=EconomyReport.parse(e.properties,e.content,merchant.shop());var plan=EconomySupply.parse(e.properties,e.content,report);return on(e.store.report(first,report,"capital"),e.owner).thenCompose(view->{check(p,view.tick()==4&&!view.markets().isEmpty()&&!view.facilities().isEmpty()&&!view.events().isEmpty(),"production_inputs_consumption_transport_prices_and_registered_event_reports_reused");return on(e.store.supply(first,report,e.merchants,plan,"iron_ingot"),e.owner);}).thenAccept(view->check(p,!view.nodes().isEmpty()&&!view.steps().isEmpty(),"public_supply_chain_and_play_guidance_reused"));})
            .thenCompose(v->on(e.store.account(first),e.owner)).thenAccept(account->expected.setProperty("first.balance",Long.toString(account.balance())))
            .thenCompose(v->on(e.store.account(second),e.owner)).thenAccept(account->expected.setProperty("second.balance",Long.toString(account.balance())))
            .thenCompose(v->on(e.store.snapshot(e.settings.realm()),e.owner)).thenAccept(state->{expected.setProperty("tick",Long.toString(state.tick()));expected.setProperty("markets",new TreeMap<>(state.markets()).toString());try(var out=Files.newBufferedWriter(root.resolve("native-expected.properties"),StandardOpenOption.CREATE_NEW)){expected.store(out,"Synthetic inventory control ports only; no Player");}catch(Exception failure){throw new IllegalStateException(failure);}});
    }
    private static CompletionStage<Void> waitSettled(JavaPlugin p,SurvivalEconomy e,int ticks){if(e.transactions.settled())return CompletableFuture.completedFuture(null);if(ticks>100)return CompletableFuture.failedFuture(new IllegalStateException("NATIVE_SETTLED_TIMEOUT"));var result=new CompletableFuture<Void>();Bukkit.getScheduler().runTaskLater(p,()->waitSettled(p,e,ticks+1).whenComplete((v,error)->{if(error==null)result.complete(null);else result.completeExceptionally(error);}),1);return result;}
    private static CompletionStage<Void> resume(JavaPlugin p,SurvivalEconomy e,Path root){var expected=new Properties();try(var r=Files.newBufferedReader(root.resolve("native-expected.properties"))){expected.load(r);}catch(Exception failure){return CompletableFuture.failedFuture(failure);}var first=e.store.context(e.settings.realm(),FIRST);var second=e.store.context(e.settings.realm(),SECOND);return on(e.store.account(first),e.owner).thenAccept(a->check(p,Long.toString(a.balance()).equals(expected.getProperty("first.balance")),"first_native_wallet_restored_in_second_JVM"))
        .thenCompose(v->on(e.store.account(second),e.owner)).thenAccept(a->check(p,Long.toString(a.balance()).equals(expected.getProperty("second.balance")),"second_native_wallet_restored_in_second_JVM"))
        .thenCompose(v->on(e.store.snapshot(e.settings.realm()),e.owner)).thenAccept(state->check(p,Long.toString(state.tick()).equals(expected.getProperty("tick"))&&new TreeMap<>(state.markets()).toString().equals(expected.getProperty("markets")),"offline_PAUSE_and_market_production_state_restore_without_reinitialization"))
        .thenCompose(v->on(e.store.history(first,Long.MAX_VALUE,20),e.owner)).thenAccept(rows->check(p,rows.size()==2,"original_shop_history_restores_without_duplicate_receipts"))
        .thenCompose(v->on(e.store.peerReceipt(first,request(3)),e.owner)).thenAccept(row->check(p,row.isPresent(),"peer_receipt_survives_new_JVM"))
        .thenRun(()->{check(p,e.journal.held(ROLLBACK)&&e.journal.held(UNKNOWN)&&e.journal.held(STALE)&&e.journal.pending().size()==3,"pending_native_holds_restore_without_profile_overwrite_or_reissue");var port=new InventoryPort(UNKNOWN,new PaperInventoryCodec(),4,false);boolean[] ran={false};var blocked=e.transactions.begin(UUID.randomUUID(),"SHOP",List.of(port),(before,valid)->{ran[0]=true;return CompletableFuture.failedFuture(new IllegalStateException());});check(p,blocked.toCompletableFuture().isCompletedExceptionally()&&!ran[0]&&port.applies==0,"reconnecting_held_actor_cannot_start_another_native_economy_transaction");});}
}
